export const KIND = {"id":54,"example":{"id":"E54","kind":54,"source":"aether","statement":["Write a class `compass::heading` whose objects each hold a direction in whole degrees, from 0 to 359.","Its constructor takes a number of degrees as an `int`, and keeps it turned into the range 0 to 359: 360 is 0 and -90 is 270.","`heading::north()` returns the heading at 0 degrees.","`turned(int degrees)` returns the heading that many degrees further round; a negative number turns back.","`degrees()` returns the degrees the heading holds.","`==` and `!=` compare two headings by their degrees.","Limits: -100 000 ≤ degrees ≤ 100 000."],"examples":[],"tests":[],"solution":{"lines":["#pragma once","","namespace compass {","","class heading {","public:","    explicit heading(int degrees)","        : degrees_ {(degrees % 360 + 360) % 360}","    {","    }","    static heading north()","    {","        return heading {0};","    }","    heading turned(int degrees) const","    {","        return heading {degrees_ + degrees};","    }","    int degrees() const","    {","        return degrees_;","    }","    bool operator==(const heading& other) const = default;","private:","    int degrees_ {0};","};","","}  // namespace compass"],"frame":[0,2,25,27],"labels":[{"at":4,"level":1,"text":"Write a class with a constructor that sets the data."},{"at":10,"level":1,"text":"Write a member function that gives back a value worked out in one step."},{"at":10,"level":0,"text":"Mark a member function `static` when it needs no object, and call it as `heading::north()`."},{"at":14,"level":1,"text":"Write a member function that gives back a value worked out in one step."},{"at":16,"level":0,"text":"Make a new object of the class with its name and the value in `{ }`."},{"at":18,"level":1,"text":"Write a member function that gives back a value worked out in one step."},{"at":22,"level":1,"text":"Compare 2 objects by their values with `==` and `!=`."},{"at":22,"level":0,"text":"Write `operator==` as `= default`, which compares each member, and `!=` comes with it."},{"at":23,"level":1,"text":"Keep the data in private members."}],"blanks":[]}},"trace":{"id":"T54","lines":["#include <iostream>","#include <print>","","int later(int hour, int more)","{","    return (hour + more) % 24;","}","","int main()","{","    int more {0};","    std::cin >> more;","    const int hour {later(20, more)};","    std::println(\"{}\", hour);","}"],"columns":["hour","more"],"inputs":["7\n","30\n"],"rows":[{"line":11,"values":["","0"]},{"line":12,"values":["","7"]},{"line":6,"values":["20","7"]},{"line":13,"values":["3","7"]},{"line":14,"values":["3","7"]}],"output":"2\n"},"traces":[],"problems":{"54.01":{"id":"54.01","kind":54,"source":"exercism","statement":["Write a class `date_independent::clock` whose objects each hold a time of day, in hours and minutes, with no date.","`clock::at(int hour, int minute)` returns the clock at that time; `minute` is 0 when left out.","Hours and minutes roll over in both directions: 25:00 is 01:00, 1:60 is 02:00, -1:15 is 23:15 and 1:-40 is 00:20.","`plus(int minutes)` returns the clock that many minutes later; a negative number goes earlier.","Turning a clock into `std::string` gives the time as `HH:MM`, each part 2 digits (`08:00`).","`==` and `!=` compare two clocks by the time they show.","Limits: -1000 ≤ hour ≤ 1000, -100 000 ≤ minute ≤ 100 000, -100 000 ≤ minutes added ≤ 100 000."],"examples":[{"input":"time_tests","output":""}],"tests":[{"input":"add_tests","output":""},{"input":"equal_tests","output":""}],"solution":{"lines":["#pragma once","","#include <format>","#include <string>","","namespace date_independent {","","class clock {","public:","    explicit clock(int minutes)","        : minutes_ {(minutes % 1440 + 1440) % 1440}","    {","    }","    static clock at(int hour, int minute = 0)","    {","        return clock {hour * 60 + minute};","    }","    clock plus(int minutes) const","    {","        return clock {minutes_ + minutes};","    }","    operator std::string() const","    {","        return std::format(\"{:02}:{:02}\", minutes_ / 60,","                           minutes_ % 60);","    }","    bool operator==(const clock& other) const = default;","private:","    int minutes_ {0};","};","","}  // namespace date_independent"],"frame":[0,2,3,5,29,31],"labels":[{"at":7,"level":1,"text":"Write a class with a constructor that sets the data."},{"at":13,"level":1,"text":"Write a member function that gives back a value worked out in one step."},{"at":17,"level":1,"text":"Write a member function that gives back a value worked out in one step."},{"at":21,"level":1,"text":"Write a member function that gives back a value worked out in one step."},{"at":26,"level":1,"text":"Compare 2 objects by their values with `==` and `!=`."},{"at":27,"level":1,"text":"Keep the data in private members."}],"blanks":[{"line":9,"from":19,"to":30},{"line":13,"from":20,"to":44},{"line":17,"from":15,"to":26},{"line":23,"from":42,"to":55},{"line":26,"from":48,"to":55},{"line":28,"from":18,"to":19}]},"fn":{"slug":"clock","commit":"8d139cb0","header":"clock.h","name":"clock_test.cpp","test":"#include \"clock.h\"\n#ifdef EXERCISM_TEST_SUITE\n#include <catch2/catch.hpp>\n#else\n#include \"test/catch.hpp\"\n#endif\n#include <sstream>\n\nusing namespace std;\n\nstruct timeTest {\n    int hour;\n    int minute;\n    string expected;\n    string msg;\n};\n\nvector<timeTest> timeCases = {\n    {8, 0, \"08:00\", \"on the hour\"},\n    {11, 9, \"11:09\", \"past the hour\"},\n    {24, 0, \"00:00\", \"midnight is zero hours\"},\n    {25, 0, \"01:00\", \"hour rolls over\"},\n    {100, 0, \"04:00\", \"hour rolls over continuously\"},\n    {1, 60, \"02:00\", \"sixty minutes is next hour\"},\n    {0, 160, \"02:40\", \"minutes roll over\"},\n    {0, 1723, \"04:43\", \"minutes roll over continuously\"},\n    {25, 160, \"03:40\", \"hour and minutes roll over\"},\n    {201, 3001, \"11:01\", \"hour and minutes roll over continuously\"},\n    {72, 8640, \"00:00\", \"hour and minutes roll over to exactly midnight\"},\n    {-1, 15, \"23:15\", \"negative hour\"},\n    {-25, 0, \"23:00\", \"negative hour rolls over\"},\n    {-91, 0, \"05:00\", \"negative hour rolls over continuously\"},\n    {1, -40, \"00:20\", \"negative minutes\"},\n    {1, -160, \"22:20\", \"negative minutes roll over\"},\n    {1, -4820, \"16:40\", \"negative minutes roll over continuously\"},\n    {-25, -160, \"20:20\", \"negative hour and minutes both roll over\"},\n    {-121, -5810, \"22:10\",\n     \"negative hour and minutes both roll over continuously\"},\n};\n\nstruct addTest {\n    int hour;\n    int minute;\n    int add;\n    string expected;\n    string msg;\n};\n\nvector<addTest> addCases = {\n    {10, 0, 3, \"10:03\", \"add minutes\"},\n    {6, 41, 0, \"06:41\", \"add no minutes\"},\n    {0, 45, 40, \"01:25\", \"add to next hour\"},\n    {10, 0, 61, \"11:01\", \"add more than one hour\"},\n    {0, 45, 160, \"03:25\", \"add more than two hours with carry\"},\n    {23, 59, 2, \"00:01\", \"add across midnight\"},\n    {5, 32, 1500, \"06:32\", \"add more than one day (1500 min = 25 hrs)\"},\n    {1, 1, 3500, \"11:21\", \"add more than two days\"},\n    {10, 3, -3, \"10:00\", \"subtract minutes\"},\n    {10, 3, -30, \"09:33\", \"subtract to previous hour\"},\n    {10, 3, -70, \"08:53\", \"subtract more than an hour\"},\n    {0, 3, -4, \"23:59\", \"subtract across midnight\"},\n    {0, 0, -160, \"21:20\", \"subtract more than two hours\"},\n    {6, 15, -160, \"03:35\", \"subtract more than two hours with borrow\"},\n    {5, 32, -1500, \"04:32\", \"subtract more than one day (1500 min = 25 hrs)\"},\n    {2, 20, -3000, \"00:20\", \"subtract more than two days\"},\n};\n\n// Construct two separate clocks, set times, test if they are equal.\nstruct hm {\n    int hour;\n    int minute;\n};\n\nstruct equalTest {\n    string msg;\n    hm c1;\n    hm c2;\n    bool expected;\n};\n\nvector<equalTest> equalCases = {\n    {\n        \"clocks with same time\",\n        hm{15, 37},\n        hm{15, 37},\n        true,\n    },\n    {\n        \"clocks a minute apart\",\n        hm{15, 36},\n        hm{15, 37},\n        false,\n    },\n    {\n        \"clocks an hour apart\",\n        hm{14, 37},\n        hm{15, 37},\n        false,\n    },\n    {\n        \"clocks with hour overflow\",\n        hm{10, 37},\n        hm{34, 37},\n        true,\n    },\n    {\n        \"clocks with hour overflow by several days\",\n        hm{3, 11},\n        hm{99, 11},\n        true,\n    },\n    {\n        \"clocks with negative hour\",\n        hm{22, 40},\n        hm{-2, 40},\n        true,\n    },\n    {\n        \"clocks with negative hour that wraps\",\n        hm{17, 3},\n        hm{-31, 3},\n        true,\n    },\n    {\n        \"clocks with negative hour that wraps multiple times\",\n        hm{13, 49},\n        hm{-83, 49},\n        true,\n    },\n    {\n        \"clocks with minute overflow\",\n        hm{0, 1},\n        hm{0, 1441},\n        true,\n    },\n    {\n        \"clocks with minute overflow by several days\",\n        hm{2, 2},\n        hm{2, 4322},\n        true,\n    },\n    {\n        \"clocks with negative minute\",\n        hm{2, 40},\n        hm{3, -20},\n        true,\n    },\n    {\n        \"clocks with negative minute that wraps\",\n        hm{4, 10},\n        hm{5, -1490},\n        true,\n    },\n    {\n        \"clocks with negative minute that wraps multiple times\",\n        hm{6, 15},\n        hm{6, -4305},\n        true,\n    },\n    {\n        \"clocks with negative hours and minutes\",\n        hm{7, 32},\n        hm{-12, -268},\n        true,\n    },\n    {\n        \"clocks with negative hours and minutes that wrap\",\n        hm{18, 7},\n        hm{-54, -11513},\n        true,\n    },\n};\n\nstring errorMsg(string expected, string actual, string test) {\n    stringstream ret;\n    ret << \"[\" << expected << \" != \" << actual << \"] test case: \" << test;\n    return ret.str();\n}\n\nTEST_CASE(\"time_tests\") {\n    for (timeTest t : timeCases) {\n        const auto actual =\n            string(date_independent::clock::at(t.hour, t.minute));\n\n        INFO(errorMsg(t.expected, actual, t.msg));\n        REQUIRE(t.expected == actual);\n    }\n}\n\n#if defined(EXERCISM_RUN_ALL_TESTS)\nTEST_CASE(\"add_tests\") {\n    for (addTest a : addCases) {\n        const auto actual =\n            string(date_independent::clock::at(a.hour, a.minute).plus(a.add));\n\n        INFO(errorMsg(a.expected, actual, a.msg));\n        REQUIRE(a.expected == actual);\n    }\n}\n\nTEST_CASE(\"equal_tests\") {\n    for (equalTest e : equalCases) {\n        const auto clock1 = date_independent::clock::at(e.c1.hour, e.c1.minute);\n        const auto clock2 = date_independent::clock::at(e.c2.hour, e.c2.minute);\n\n        if (e.expected) {\n            INFO(errorMsg(string(clock1), string(clock2), e.msg));\n            REQUIRE(clock1 == clock2);\n        } else {\n            INFO(\"[\" << string(clock1) << \" == \" << string(clock2)\n                     << \"] test case: \" << e.msg);\n            REQUIRE(clock1 != clock2);\n        }\n    }\n}\n#endif\n","setup":["for (timeTest t : timeCases) { const auto actual = string(date_independent::clock::at(t.hour, t.minute)); INFO(errorMsg(t.expected, actual, t.msg)); REQUIRE(t.expected == actual); }"],"calls":[]}},"54.02":{"id":"54.02","kind":54,"source":"aether","statement":["Write a class `week::day` whose objects each hold a day of the week, numbered 0 for Monday to 6 for Sunday.","Its constructor takes a day number as an `int`, and keeps it turned into the range 0 to 6: 7 is 0 and -1 is 6.","`day::from(int number)` returns the day with that number.","`after(int days)` returns the day that many days later; a negative number goes earlier.","`name()` returns the day's name as a `std::string`: `Monday`, `Tuesday`, `Wednesday`, `Thursday`, `Friday`, `Saturday` or `Sunday`.","`==` and `!=` compare two days by their numbers.","Limits: -1000 ≤ number ≤ 1000; -1000 ≤ days ≤ 1000."],"examples":[{"input":"wednesday_plus_three","output":""}],"tests":[{"input":"monday_name","output":""},{"input":"sunday_name","output":""},{"input":"seven_is_monday","output":""},{"input":"minus_one_is_sunday","output":""},{"input":"largest_number","output":""},{"input":"smallest_number","output":""},{"input":"after_zero_days","output":""},{"input":"back_over_the_week","output":""},{"input":"many_days_later","output":""},{"input":"many_days_earlier","output":""},{"input":"different_days_differ","output":""}],"solution":{"lines":["#pragma once","","#include <array>","#include <string>","","namespace week {","","class day {","public:","    explicit day(int number)","        : number_ {(number % 7 + 7) % 7}","    {","    }","    static day from(int number)","    {","        return day {number};","    }","    day after(int days) const","    {","        return day {number_ + days};","    }","    std::string name() const","    {","        const std::array<std::string, 7> names {","            \"Monday\", \"Tuesday\", \"Wednesday\", \"Thursday\",","            \"Friday\", \"Saturday\", \"Sunday\"};","        return names[number_];","    }","    bool operator==(const day& other) const = default;","private:","    int number_ {0};","};","","}  // namespace week"],"frame":[0,2,3,5,31,33],"labels":[{"at":7,"level":1,"text":"Write a class with a constructor that sets the data."},{"at":13,"level":1,"text":"Write a member function that gives back a value worked out in one step."},{"at":17,"level":1,"text":"Write a member function that gives back a value worked out in one step."},{"at":21,"level":1,"text":"Write a member function that gives back a value worked out in one step."},{"at":28,"level":1,"text":"Compare 2 objects by their values with `==` and `!=`."},{"at":29,"level":1,"text":"Keep the data in private members."}],"blanks":[{"line":9,"from":17,"to":27},{"line":13,"from":20,"to":30},{"line":19,"from":20,"to":34},{"line":26,"from":15,"to":28},{"line":28,"from":46,"to":53},{"line":30,"from":17,"to":18}]},"fn":{"slug":"week","commit":"","header":"week.h","name":"week_test.cpp","test":"#include \"week.h\"\n#include \"test/catch.hpp\"\n\nTEST_CASE(\"wednesday_plus_three\") { REQUIRE(week::day::from(2).after(3).name() == \"Saturday\"); }\n#if defined(EXERCISM_RUN_ALL_TESTS)\nTEST_CASE(\"monday_name\") { REQUIRE(week::day::from(0).name() == \"Monday\"); }\nTEST_CASE(\"sunday_name\") { REQUIRE(week::day::from(6).name() == \"Sunday\"); }\nTEST_CASE(\"seven_is_monday\") { REQUIRE(week::day::from(7) == week::day::from(0)); }\nTEST_CASE(\"minus_one_is_sunday\") { REQUIRE(week::day::from(-1).name() == \"Sunday\"); }\nTEST_CASE(\"largest_number\") { REQUIRE(week::day::from(1000).name() == \"Sunday\"); }\nTEST_CASE(\"smallest_number\") { REQUIRE(week::day::from(-1000).name() == \"Tuesday\"); }\nTEST_CASE(\"after_zero_days\") { REQUIRE(week::day::from(4).after(0) == week::day::from(4)); }\nTEST_CASE(\"back_over_the_week\") { REQUIRE(week::day::from(1).after(-3).name() == \"Saturday\"); }\nTEST_CASE(\"many_days_later\") { REQUIRE(week::day::from(3).after(1000).name() == \"Wednesday\"); }\nTEST_CASE(\"many_days_earlier\") { REQUIRE(week::day::from(3).after(-1000).name() == \"Friday\"); }\nTEST_CASE(\"different_days_differ\") { REQUIRE(week::day::from(1) != week::day::from(2)); }\n#endif\n","setup":[],"calls":[{"call":"week::day::from(2).after(3).name()","expected":"\"Saturday\""}]}},"54.03":{"id":"54.03","kind":54,"source":"exercism","statement":["Write a class `complex_numbers::Complex` whose objects each hold a complex number, a real part and an imaginary part, each a `double`.","Its constructor takes the real part and the imaginary part, in that order; the imaginary part is 0 when left out.","`real()` and `imag()` return the parts.","`+`, `-`, `*` and `/` work out the sum, difference, product and quotient of 2 complex numbers, or of a complex number and a `double` on either side.","`abs()` returns the absolute value, `conj()` the conjugate and `exp()` e raised to the number.","`==` and `!=` compare two numbers by their parts.","Each part must be right to within 0.005.","Limits: none"],"examples":[{"input":"Real part -> Real part of a purely real number","output":""}],"tests":[{"input":"Real part -> Real part of a purely imaginary number","output":""},{"input":"Real part -> Real part of a number with real and imaginary part","output":""},{"input":"Imaginary part -> Imaginary part of a purely real number","output":""},{"input":"Imaginary part -> Imaginary part of a purely imaginary number","output":""},{"input":"Imaginary part -> Imaginary part of a number with real and imaginary part","output":""},{"input":"Imaginary unit","output":""},{"input":"Arithmetic -> Addition -> Add purely real numbers","output":""},{"input":"Arithmetic -> Addition -> Add purely imaginary numbers","output":""},{"input":"Arithmetic -> Addition -> Add numbers with real and imaginary part","output":""},{"input":"Arithmetic -> Subtraction -> Subtract purely real numbers","output":""},{"input":"Arithmetic -> Subtraction -> Subtract purely imaginary numbers","output":""},{"input":"Arithmetic -> Subtraction -> Subtract numbers with real and imaginary part","output":""},{"input":"Arithmetic -> Multiplication -> Multiply purely real numbers","output":""},{"input":"Arithmetic -> Multiplication -> Multiply purely imaginary numbers","output":""},{"input":"Arithmetic -> Multiplication -> Multiply numbers with real and imaginary part","output":""},{"input":"Arithmetic -> Division -> Divide purely real numbers","output":""},{"input":"Arithmetic -> Division -> Divide purely imaginary numbers","output":""},{"input":"Arithmetic -> Division -> Divide numbers with real and imaginary part","output":""},{"input":"Absolute value -> Absolute value of a positive purely real number","output":""},{"input":"Absolute value -> Absolute value of a negative purely real number","output":""},{"input":"Absolute value -> Absolute value of a purely imaginary number with positive imaginary part","output":""},{"input":"Absolute value -> Absolute value of a purely imaginary number with negative imaginary part","output":""},{"input":"Absolute value -> Absolute value of a number with real and imaginary part","output":""},{"input":"Complex conjugate -> Conjugate a purely real number","output":""},{"input":"Complex conjugate -> Conjugate a purely imaginary number","output":""},{"input":"Complex conjugate -> Conjugate a number with real and imaginary part","output":""},{"input":"Complex exponential function -> Euler's identity/formula","output":""},{"input":"Complex exponential function -> Exponential of 0","output":""},{"input":"Complex exponential function -> Exponential of a purely real number","output":""},{"input":"Complex exponential function -> Exponential of a number with real and imaginary part","output":""},{"input":"Complex exponential function -> Exponential resulting in a number with real and imaginary part","output":""},{"input":"Operations between real numbers and complex numbers -> Add real number to complex number","output":""},{"input":"Operations between real numbers and complex numbers -> Add complex number to real number","output":""},{"input":"Operations between real numbers and complex numbers -> Subtract real number from complex number","output":""},{"input":"Operations between real numbers and complex numbers -> Subtract complex number from real number","output":""},{"input":"Operations between real numbers and complex numbers -> Multiply complex number by real number","output":""},{"input":"Operations between real numbers and complex numbers -> Multiply real number by complex number","output":""},{"input":"Operations between real numbers and complex numbers -> Divide complex number by real number","output":""},{"input":"Operations between real numbers and complex numbers -> Divide real number by complex number","output":""}],"solution":{"lines":["#pragma once","","#include <cmath>","","namespace complex_numbers {","","class Complex {","public:","    Complex(double real, double imag = 0.0)","        : real_ {real}, imag_ {imag}","    {","    }","    double real() const","    {","        return real_;","    }","    double imag() const","    {","        return imag_;","    }","    double abs() const","    {","        return std::hypot(real_, imag_);","    }","    Complex conj() const","    {","        return Complex {real_, -imag_};","    }","    Complex exp() const","    {","        const double size {std::exp(real_)};","        return Complex {size * std::cos(imag_),","                        size * std::sin(imag_)};","    }","    friend Complex operator+(const Complex& a, const Complex& b)","    {","        return Complex {a.real_ + b.real_, a.imag_ + b.imag_};","    }","    friend Complex operator-(const Complex& a, const Complex& b)","    {","        return Complex {a.real_ - b.real_, a.imag_ - b.imag_};","    }","    friend Complex operator*(const Complex& a, const Complex& b)","    {","        return Complex {a.real_ * b.real_ - a.imag_ * b.imag_,","                        a.real_ * b.imag_ + a.imag_ * b.real_};","    }","    friend Complex operator/(const Complex& a, const Complex& b)","    {","        const double d {b.real_ * b.real_ + b.imag_ * b.imag_};","        return Complex {","            (a.real_ * b.real_ + a.imag_ * b.imag_) / d,","            (a.imag_ * b.real_ - a.real_ * b.imag_) / d};","    }","    bool operator==(const Complex& other) const = default;","private:","    double real_ {0.0};","    double imag_ {0.0};","};","","}  // namespace complex_numbers"],"frame":[0,2,4,58,60],"labels":[{"at":6,"level":1,"text":"Write a class with a constructor that sets the data."},{"at":12,"level":1,"text":"Write a member function that gives back a value worked out in one step."},{"at":24,"level":1,"text":"Write a member function that gives back a value worked out in one step."},{"at":34,"level":1,"text":"Write a member function that gives back a value worked out in one step."},{"at":54,"level":1,"text":"Compare 2 objects by their values with `==` and `!=`."},{"at":55,"level":1,"text":"Keep the data in private members."}],"blanks":[{"line":8,"from":12,"to":42},{"line":14,"from":15,"to":20},{"line":26,"from":31,"to":37},{"line":36,"from":24,"to":41},{"line":54,"from":50,"to":57},{"line":56,"from":18,"to":21}]},"fn":{"slug":"complex-numbers","commit":"8d139cb0","header":"complex_numbers.h","name":"complex_numbers_test.cpp","test":"#include \"complex_numbers.h\"\n\n#include <cmath>\n#include <sstream>\n\n#ifdef EXERCISM_TEST_SUITE\n#include <catch2/catch.hpp>\n#else\n#include \"test/catch_amalgamated.hpp\"\n#endif\n\n// Complex Numbers exercise test case data version 1.3.0\n\nusing complex_numbers::Complex;\n\n// Define constants for platforms that don't include it\n#ifndef M_PI\n#define M_PI 3.14159265358979323846\n#endif\n#ifndef M_E\n#define M_E 2.71828182845904523536\n#endif\n\n// Define a margin to use for float comparisons. Catch does not compute a good\n// epsilon for float values near 0.\nstatic constexpr double eps = 0.005;\n\n// Custom Catch2 matcher for approximate equality of Complex numbers\nclass ComplexApproxMatcher : public Catch::Matchers::MatcherBase<Complex> {\n   public:\n    ComplexApproxMatcher(const Complex& expected, double epsilon)\n        : expected{expected}, epsilon{epsilon} {}\n\n    bool match(const Complex& actual) const override {\n        return std::abs(actual.real() - expected.real()) <= epsilon &&\n               std::abs(actual.imag() - expected.imag()) <= epsilon;\n    }\n\n    std::string describe() const override {\n        std::ostringstream ss;\n        ss << \"is approximately equal to (\" << expected.real() << \", \"\n           << expected.imag() << \"i) with epsilon \" << epsilon;\n        return ss.str();\n    }\n\n   private:\n    Complex expected;\n    double epsilon;\n};\n\n// Helper function to create the matcher\ninline ComplexApproxMatcher ComplexWithinAbs(const Complex& expected,\n                                             double epsilon) {\n    return ComplexApproxMatcher{expected, epsilon};\n}\n\nTEST_CASE(\"Real part -> Real part of a purely real number\",\n          \"[9f98e133-eb7f-45b0-9676-cce001cd6f7a]\") {\n    const Complex c{1.0, 0.0};\n\n    REQUIRE_THAT(c.real(), Catch::Matchers::WithinAbs(1.0, eps));\n}\n\n#if defined(EXERCISM_RUN_ALL_TESTS)\nTEST_CASE(\"Real part -> Real part of a purely imaginary number\",\n          \"[07988e20-f287-4bb7-90cf-b32c4bffe0f3]\") {\n    const Complex c{0.0, 1.0};\n\n    REQUIRE_THAT(c.real(), Catch::Matchers::WithinAbs(0.0, eps));\n}\n\nTEST_CASE(\"Real part -> Real part of a number with real and imaginary part\",\n          \"[4a370e86-939e-43de-a895-a00ca32da60a]\") {\n    const Complex c{1.0, 2.0};\n\n    REQUIRE_THAT(c.real(), Catch::Matchers::WithinAbs(1.0, eps));\n}\n\nTEST_CASE(\"Imaginary part -> Imaginary part of a purely real number\",\n          \"[9b3fddef-4c12-4a99-b8f8-e3a42c7ccef6]\") {\n    const Complex c{1.0, 0.0};\n\n    REQUIRE_THAT(c.imag(), Catch::Matchers::WithinAbs(0.0, eps));\n}\n\nTEST_CASE(\"Imaginary part -> Imaginary part of a purely imaginary number\",\n          \"[a8dafedd-535a-4ed3-8a39-fda103a2b01e]\") {\n    const Complex c{0.0, 1.0};\n\n    REQUIRE_THAT(c.imag(), Catch::Matchers::WithinAbs(1.0, eps));\n}\n\nTEST_CASE(\n    \"Imaginary part -> Imaginary part of a number with real and imaginary part\",\n    \"[0f998f19-69ee-4c64-80ef-01b086feab80]\") {\n    const Complex c{1.0, 2.0};\n\n    REQUIRE_THAT(c.imag(), Catch::Matchers::WithinAbs(2.0, eps));\n}\n\nTEST_CASE(\"Imaginary unit\", \"[a39b7fd6-6527-492f-8c34-609d2c913879]\") {\n    const Complex c1{0.0, 1.0};\n    const Complex c2{0.0, 1.0};\n\n    REQUIRE_THAT(c1 * c2, ComplexWithinAbs(Complex{-1.0, 0.0}, eps));\n}\n\nTEST_CASE(\"Arithmetic -> Addition -> Add purely real numbers\",\n          \"[9a2c8de9-f068-4f6f-b41c-82232cc6c33e]\") {\n    const Complex c1{1.0, 0.0};\n    const Complex c2{2.0, 0.0};\n\n    REQUIRE_THAT(c1 + c2, ComplexWithinAbs(Complex{3.0, 0.0}, eps));\n}\n\nTEST_CASE(\"Arithmetic -> Addition -> Add purely imaginary numbers\",\n          \"[657c55e1-b14b-4ba7-bd5c-19db22b7d659]\") {\n    const Complex c1{0.0, 1.0};\n    const Complex c2{0.0, 2.0};\n\n    REQUIRE_THAT(c1 + c2, ComplexWithinAbs(Complex{0.0, 3.0}, eps));\n}\n\nTEST_CASE(\"Arithmetic -> Addition -> Add numbers with real and imaginary part\",\n          \"[4e1395f5-572b-4ce8-bfa9-9a63056888da]\") {\n    const Complex c1{1.0, 2.0};\n    const Complex c2{3.0, 4.0};\n\n    REQUIRE_THAT(c1 + c2, ComplexWithinAbs(Complex{4.0, 6.0}, eps));\n}\n\nTEST_CASE(\"Arithmetic -> Subtraction -> Subtract purely real numbers\",\n          \"[1155dc45-e4f7-44b8-af34-a91aa431475d]\") {\n    const Complex c1{1.0, 0.0};\n    const Complex c2{2.0, 0.0};\n\n    REQUIRE_THAT(c1 - c2, ComplexWithinAbs(Complex{-1.0, 0.0}, eps));\n}\n\nTEST_CASE(\"Arithmetic -> Subtraction -> Subtract purely imaginary numbers\",\n          \"[f95e9da8-acd5-4da4-ac7c-c861b02f774b]\") {\n    const Complex c1{0.0, 1.0};\n    const Complex c2{0.0, 2.0};\n\n    REQUIRE_THAT(c1 - c2, ComplexWithinAbs(Complex{0.0, -1.0}, eps));\n}\n\nTEST_CASE(\n    // clang-format off\n    \"Arithmetic -> Subtraction -> Subtract numbers with real and imaginary part\",\n    // clang-format on\n    \"[f876feb1-f9d1-4d34-b067-b599a8746400]\") {\n    const Complex c1{1.0, 2.0};\n    const Complex c2{3.0, 4.0};\n\n    REQUIRE_THAT(c1 - c2, ComplexWithinAbs(Complex{-2.0, -2.0}, eps));\n}\n\nTEST_CASE(\"Arithmetic -> Multiplication -> Multiply purely real numbers\",\n          \"[8a0366c0-9e16-431f-9fd7-40ac46ff4ec4]\") {\n    const Complex c1{1.0, 0.0};\n    const Complex c2{2.0, 0.0};\n\n    REQUIRE_THAT(c1 * c2, ComplexWithinAbs(Complex{2.0, 0.0}, eps));\n}\n\nTEST_CASE(\"Arithmetic -> Multiplication -> Multiply purely imaginary numbers\",\n          \"[e560ed2b-0b80-4b4f-90f2-63cefc911aaf]\") {\n    const Complex c1{0.0, 1.0};\n    const Complex c2{0.0, 2.0};\n\n    REQUIRE_THAT(c1 * c2, ComplexWithinAbs(Complex{-2.0, 0.0}, eps));\n}\n\nTEST_CASE(\n    // clang-format off\n    \"Arithmetic -> Multiplication -> Multiply numbers with real and imaginary part\",\n    // clang-format on\n    \"[4d1d10f0-f8d4-48a0-b1d0-f284ada567e6]\") {\n    const Complex c1{1.0, 2.0};\n    const Complex c2{3.0, 4.0};\n\n    REQUIRE_THAT(c1 * c2, ComplexWithinAbs(Complex{-5.0, 10.0}, eps));\n}\n\nTEST_CASE(\"Arithmetic -> Division -> Divide purely real numbers\",\n          \"[b0571ddb-9045-412b-9c15-cd1d816d36c1]\") {\n    const Complex c1{1.0, 0.0};\n    const Complex c2{2.0, 0.0};\n\n    REQUIRE_THAT(c1 / c2, ComplexWithinAbs(Complex{0.5, 0.0}, eps));\n}\n\nTEST_CASE(\"Arithmetic -> Division -> Divide purely imaginary numbers\",\n          \"[5bb4c7e4-9934-4237-93cc-5780764fdbdd]\") {\n    const Complex c1{0.0, 1.0};\n    const Complex c2{0.0, 2.0};\n\n    REQUIRE_THAT(c1 / c2, ComplexWithinAbs(Complex{0.5, 0.0}, eps));\n}\n\nTEST_CASE(\n    \"Arithmetic -> Division -> Divide numbers with real and imaginary part\",\n    \"[c4e7fef5-64ac-4537-91c2-c6529707701f]\") {\n    const Complex c1{1.0, 2.0};\n    const Complex c2{3.0, 4.0};\n\n    REQUIRE_THAT(c1 / c2, ComplexWithinAbs(Complex{0.44, 0.08}, eps));\n}\n\nTEST_CASE(\"Absolute value -> Absolute value of a positive purely real number\",\n          \"[c56a7332-aad2-4437-83a0-b3580ecee843]\") {\n    const Complex c{5.0, 0.0};\n\n    REQUIRE_THAT(c.abs(), Catch::Matchers::WithinAbs(5.0, eps));\n}\n\nTEST_CASE(\"Absolute value -> Absolute value of a negative purely real number\",\n          \"[cf88d7d3-ee74-4f4e-8a88-a1b0090ecb0c]\") {\n    const Complex c{-5.0, 0.0};\n\n    REQUIRE_THAT(c.abs(), Catch::Matchers::WithinAbs(5.0, eps));\n}\n\nTEST_CASE(\n    // clang-format off\n    \"Absolute value -> Absolute value of a purely imaginary number with positive imaginary part\",\n    // clang-format on\n    \"[bbe26568-86c1-4bb4-ba7a-da5697e2b994]\") {\n    const Complex c{0.0, 5.0};\n\n    REQUIRE_THAT(c.abs(), Catch::Matchers::WithinAbs(5.0, eps));\n}\n\nTEST_CASE(\n    // clang-format off\n    \"Absolute value -> Absolute value of a purely imaginary number with negative imaginary part\",\n    // clang-format on\n    \"[3b48233d-468e-4276-9f59-70f4ca1f26f3]\") {\n    const Complex c{0.0, -5.0};\n\n    REQUIRE_THAT(c.abs(), Catch::Matchers::WithinAbs(5.0, eps));\n}\n\nTEST_CASE(\n    \"Absolute value -> Absolute value of a number with real and imaginary part\",\n    \"[fe400a9f-aa22-4b49-af92-51e0f5a2a6d3]\") {\n    const Complex c{3.0, 4.0};\n\n    REQUIRE_THAT(c.abs(), Catch::Matchers::WithinAbs(5.0, eps));\n}\n\nTEST_CASE(\"Complex conjugate -> Conjugate a purely real number\",\n          \"[fb2d0792-e55a-4484-9443-df1eddfc84a2]\") {\n    const Complex c{5.0, 0.0};\n\n    REQUIRE_THAT(c.conj(), ComplexWithinAbs(Complex{5.0, 0.0}, eps));\n}\n\nTEST_CASE(\"Complex conjugate -> Conjugate a purely imaginary number\",\n          \"[e37fe7ac-a968-4694-a460-66cb605f8691]\") {\n    const Complex c{0.0, 5.0};\n\n    REQUIRE_THAT(c.conj(), ComplexWithinAbs(Complex{0.0, -5.0}, eps));\n}\n\nTEST_CASE(\n    \"Complex conjugate -> Conjugate a number with real and imaginary part\",\n    \"[f7704498-d0be-4192-aaf5-a1f3a7f43e68]\") {\n    const Complex c{1.0, 1.0};\n\n    REQUIRE_THAT(c.conj(), ComplexWithinAbs(Complex{1.0, -1.0}, eps));\n}\n\nTEST_CASE(\"Complex exponential function -> Euler's identity/formula\",\n          \"[6d96d4c6-2edb-445b-94a2-7de6d4caaf60]\") {\n    const Complex c{0.0, M_PI};\n\n    REQUIRE_THAT(c.exp(), ComplexWithinAbs(Complex{-1.0, 0.0}, eps));\n}\n\nTEST_CASE(\"Complex exponential function -> Exponential of 0\",\n          \"[2d2c05a0-4038-4427-a24d-72f6624aa45f]\") {\n    const Complex c{0.0, 0.0};\n\n    REQUIRE_THAT(c.exp(), ComplexWithinAbs(Complex{1.0, 0.0}, eps));\n}\n\nTEST_CASE(\"Complex exponential function -> Exponential of a purely real number\",\n          \"[ed87f1bd-b187-45d6-8ece-7e331232c809]\") {\n    const Complex c{1.0, 0.0};\n\n    REQUIRE_THAT(c.exp(), ComplexWithinAbs(Complex(M_E, 0.0), eps));\n}\n\n// Extra Credit\nTEST_CASE(\n    // clang-format off\n    \"Complex exponential function -> Exponential of a number with real and imaginary part\",\n    // clang-format on\n    \"[08eedacc-5a95-44fc-8789-1547b27a8702]\") {\n    const Complex c{std::log(2.0), M_PI};\n\n    REQUIRE_THAT(c.exp(), ComplexWithinAbs(Complex{-2.0, 0.0}, eps));\n}\n\nTEST_CASE(\n    // clang-format off\n    \"Complex exponential function -> Exponential resulting in a number with real and imaginary part\",\n    // clang-format on\n    \"[d2de4375-7537-479a-aa0e-d474f4f09859]\") {\n    const Complex c{std::log(2.0) / 2.0, M_PI / 4.0};\n\n    REQUIRE_THAT(c.exp(), ComplexWithinAbs(Complex{1.0, 1.0}, eps));\n}\n\nTEST_CASE(\n    // clang-format off\n    \"Operations between real numbers and complex numbers -> Add real number to complex number\",\n    // clang-format on\n    \"[06d793bf-73bd-4b02-b015-3030b2c952ec]\") {\n    const Complex c{1.0, 2.0};\n\n    REQUIRE_THAT(c + 5.0, ComplexWithinAbs(Complex{6.0, 2.0}, eps));\n}\n\nTEST_CASE(\n    // clang-format off\n    \"Operations between real numbers and complex numbers -> Add complex number to real number\",\n    // clang-format on\n    \"[d77dbbdf-b8df-43f6-a58d-3acb96765328]\") {\n    const Complex c{1.0, 2.0};\n\n    REQUIRE_THAT(5.0 + c, ComplexWithinAbs(Complex{6.0, 2.0}, eps));\n}\n\nTEST_CASE(\n    // clang-format off\n    \"Operations between real numbers and complex numbers -> Subtract real number from complex number\",\n    // clang-format on\n    \"[20432c8e-8960-4c40-ba83-c9d910ff0a0f]\") {\n    const Complex c{5.0, 7.0};\n\n    REQUIRE_THAT(c - 4.0, ComplexWithinAbs(Complex{1.0, 7.0}, eps));\n}\n\nTEST_CASE(\n    // clang-format off\n    \"Operations between real numbers and complex numbers -> Subtract complex number from real number\",\n    // clang-format on\n    \"[b4b38c85-e1bf-437d-b04d-49bba6e55000]\") {\n    const Complex c{5.0, 7.0};\n\n    REQUIRE_THAT(4.0 - c, ComplexWithinAbs(Complex{-1.0, -7.0}, eps));\n}\n\nTEST_CASE(\n    // clang-format off\n    \"Operations between real numbers and complex numbers -> Multiply complex number by real number\",\n    // clang-format on\n    \"[dabe1c8c-b8f4-44dd-879d-37d77c4d06bd]\") {\n    const Complex c{2.0, 5.0};\n\n    REQUIRE_THAT(c * 5.0, ComplexWithinAbs(Complex{10.0, 25.0}, eps));\n}\n\nTEST_CASE(\n    // clang-format off\n    \"Operations between real numbers and complex numbers -> Multiply real number by complex number\",\n    // clang-format on\n    \"[6c81b8c8-9851-46f0-9de5-d96d314c3a28]\") {\n    const Complex c{2.0, 5.0};\n\n    REQUIRE_THAT(5.0 * c, ComplexWithinAbs(Complex{10.0, 25.0}, eps));\n}\n\nTEST_CASE(\n    // clang-format off\n    \"Operations between real numbers and complex numbers -> Divide complex number by real number\",\n    // clang-format on\n    \"[8a400f75-710e-4d0c-bcb4-5e5a00c78aa0]\") {\n    const Complex c{10.0, 100.0};\n\n    REQUIRE_THAT(c / 10.0, ComplexWithinAbs(Complex{1.0, 10.0}, eps));\n}\n\nTEST_CASE(\n    // clang-format off\n    \"Operations between real numbers and complex numbers -> Divide real number by complex number\",\n    // clang-format on\n    \"[9a867d1b-d736-4c41-a41e-90bd148e9d5e]\") {\n    const Complex c{1.0, 1.0};\n\n    REQUIRE_THAT(5.0 / c, ComplexWithinAbs(Complex{2.5, -2.5}, eps));\n}\n\n#endif\n","setup":["const Complex c{1.0, 0.0};","REQUIRE_THAT(c.real(), Catch::Matchers::WithinAbs(1.0, eps));"],"calls":[]}}}}
